 const ensureTenant=async user=>{const{data:members,error:memberError}=await supabase.from('tenant_members').select('tenant_id').eq('user_id',user.id).limit(1);if(memberError)throw memberError;if(members?.[0]?.tenant_id)return members[0].tenant_id;const slug='mockupro-'+String(user.id).replace(/-/g,'');const name=(user.email?.split('@')[0]||'Mi empresa')+' · MockuPro';const{data,error}=await supabase.from('tenants').insert({name,slug,created_by:user.id}).select('id').single();if(error){const{data:retry}=await supabase.from('tenant_members').select('tenant_id').eq('user_id',user.id).limit(1);if(retry?.[0]?.tenant_id)return retry[0].tenant_id;throw error}return data.id};
